#[cfg(test)]
mod rbp_binary_tests {
    use super::*;
    use crate::cancel_reject::*;
    use crate::cancel_req::*;
    use crate::instr_ack::*;
    use crate::instruction::*;
    use crate::new_order_req::*;
    use crate::order_confirm::*;
    use crate::order_reject::*;
    use crate::risk_result::*;
    use crate::trade_report::*;
    use bytes::BytesMut;

    #[test]
    fn test_rbp_binary_codec() {
        let mut original = RbpBinary {
            version: 1234,
            flags: 1234,
            msg_seq: 123456789,
            ts_ns: 123456789,
            body_len: 0,
            checksum: 123456,
            msg_type: 16,
            body: RbpBinaryBodyEnum::NewOrderReq(NewOrderReq {
                req_id: 123456789,
                channel_id: 1234,
                adapter: 42,
                account: "a".repeat(16),
                account_group: "a".repeat(16),
                cl_ord_id: "a".repeat(16),
                security_id: "a".repeat(12),
                market: 42,
                side: 42,
                price: -123456789,
                order_qty: -123456789,
                ord_type: 42,
                time_in_force: 42,
                pbu: "a".repeat(8),
                transact_time: 123456789,
                ts_recv_ns: 123456789,
                raw_ref: 123456789,
            }),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(RbpBinaryRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        RbpBinary::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = RbpBinary::decode(&mut bytes).unwrap();
        original.body_len = decoded.body_len;
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

